$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-iphone-card-shape-h1.mjs'
try {
[System.IO.File]::WriteAllText($tmp,@'
setTimeout(()=>{console.log(JSON.stringify({error:'hard_timeout'}));process.exit(0)},6500);
try{const arr=await(await fetch('http://127.0.0.1:17447/json/list')).json();const t=arr.find(x=>x.id==='EF27777D4E798E704D04D5D474887AFA');if(!t)throw Error('MISSING');const w=new WebSocket(t.webSocketDebuggerUrl);
